tool_input.content:
const base = process.argv[2];
const { handle } = await import(base + '/src/api.js');
const { reset, queryLog } = await import(base + '/src/db.js');
const { dueReminders } = await import(base + '/src/scheduler.js');
const c = (body) => handle({ method: 'POST', path: '/reminders', body });
const show = (label, fn) => { try { console.log(label, JSON.stringify(fn())); } catch (e) { console.log(label, 'THROWS:', e.message); } };

reset();
c({ userId: 'alice', text: 'secret: bank pin 1234', at: '2026-03-01T09:00' });
c({ userId: 'bob', text: 'gym', at: '2026-03-01T09:00' });
show('1 search injection (bob reads alice):', () => handle({ method: 'GET', path: '/reminders/search', query: { userId: "alice' AND text LIKE '%", q: '' } }).body.map(r => r.user_id + ':' + r.text));
show('1b last SQL:', () => queryLog.at(-1).sql);
show('1c q with " and " text:', () => handle({ method: 'GET', path: '/reminders/search', query: { userId: 'bob', q: 'gym and swim' } }));
show('1d q=% wildcard:', () => handle({ method: 'GET', path: '/reminders/search', query: { userId: 'bob', q: '%' } }).body.length);
show('2 bad at:', () => c({ userId: 'u', text: 't', at: 'tomorrow' }));
show('2b at with seconds:', () => c({ userId: 'u', text: 't', at: '2026-03-01T09:00:00' }).body.due_ms);
show('2c tz string:', () => c({ userId: 'u', text: 't', at: '2026-03-01T09:00', tzOffsetMin: 'abc' }).body);
show('3 list no query:', () => handle({ method: 'GET', path: '/reminders' }));
show('3b search no userId:', () => { handle({ method: 'GET', path: '/reminders/search', query: { q: 'x' } }); return queryLog.at(-1).sql; });
show('4 delete with no owner check:', () => handle({ method: 'DELETE', path: '/reminders/1' }).status);

reset();
const r = c({ userId: 'in', text: 'x', at: '2026-03-01T09:00', tzOffsetMin: 330 }).body;
console.log('5 IST 09:00 (true UTC 03:30Z) due_ms =', new Date(r.due_ms).toISOString());
console.log('5b scheduler says due at 22:00Z prev day?', dueReminders([r], Date.parse('2026-02-28T22:00:00Z')).length === 1);
